(function(){function a(t){return t.right-t.left}function l(t){return t.bottom-t.top}function M(t,n,e){return Math.min(e,Math.max(n,t))}function s(t,n){return Math.abs(Math.log(t)-Math.log(n))}function h(t){const n=String(t).split(":");if(n.length!==2)return null;const e=Number(n[0]);const o=Number(n[1]);return Number.isFinite(e)&&Number.isFinite(o)&&e>0&&o>0?e/o:null}function u(t,n){let e=null;let o=Infinity;for(const r of n||[]){const i=h(r);if(!i)continue;const c=s(t,i);if(c<o){o=c;e=r}}return e}function g(t){const{bounds:n}=t;const e=a(n);const o=l(n);return{bounds:{left:n.left,top:n.top,right:n.right,bottom:n.bottom},ratioKey:u(e/o,t.ratios||[]),w:e,h:o}}function b(t){const{placedBounds:n,captureBounds:e}=t;const o=t.tolerance??.005;const r=a(n);const i=l(n);const c=a(e);const f=l(e);const m=r/i;const p=c/f;const F=Math.max(c/r,f/i);return{percent:F*100,ratioMismatch:s(m,p)>Math.log(1+o),placedRatio:m,captureRatio:p}}function y(t,n){return{dx:(n.left+n.right)/2-(t.left+t.right)/2,dy:(n.top+n.bottom)/2-(t.top+t.bottom)/2}}function d(t){if(!Array.isArray(t)||t.length<8)return null;const n=[t[0],t[2],t[4],t[6]];const e=[t[1],t[3],t[5],t[7]];if(![...n,...e].every(Number.isFinite))return null;return{left:Math.min(...n),top:Math.min(...e),right:Math.max(...n),bottom:Math.max(...e)}}function w(t){const n=Math.min(a(t),l(t));return Math.min(M(Math.round(.01*n),2,24),Math.floor(n/12))}const x=typeof window!=="undefined"?window:globalThis;x.nanoBananaGeometry={parseRatio:h,nearestRatioKey:u,planGeneration:g,planPlacement:b,centerDelta:y,boundsFromTransformQuad:d,revealFeatherRadius:w}})();
